// This tool identifies the Terraform documentation files that correspond to
// autogenerated (serviceapi) resources, based on tools/codegen/config.yml.
// Its output is used to decide when the Docs team should be notified and asked
// for review: autogenerated docs are excluded, as feedback for them belongs to
// the backend side (see tools/codegen).
package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"slices"
	"sort"
	"strings"

	"github.com/mongodb/terraform-provider-mongodbatlas/tools/codegen/config"
	"gopkg.in/yaml.v3"
)

const (
	configPath     = "tools/codegen/config.yml"
	codeownersPath = ".github/CODEOWNERS"
	docsOwner      = "@mongodb/APIx-Integrations"
	beginMarker    = "# BEGIN autogenerated docs ownership (generated by `go run ./tools/autogendocslist -codeowners`, do not edit)"
	endMarker      = "# END autogenerated docs ownership"
)

// genericAPIGlobs cover docs for autogenerated resources whose name ends with
// _api. They are generated through the generic tfplugindocs template and moved
// by scripts/generate-docs-all.sh based on this naming convention.
var genericAPIGlobs = []string{
	"docs/resources/*_api.md",
	"docs/resources/*_api_v*.md",
	"docs/data-sources/*_api.md",
	"docs/data-sources/*_api_v*.md",
	"docs/ephemeral-resources/*_api.md",
	"docs/ephemeral-resources/*_api_v*.md",
}

// These docs remain handwritten even though their implementations use serviceapi.
// See the documentation comments in tools/codegen/config.yml.
var handwrittenDocs = map[string]bool{
	"docs/resources/privatelink_endpoint_service_data_federation_online_archive.md":     true,
	"docs/data-sources/privatelink_endpoint_service_data_federation_online_archive.md":  true,
	"docs/data-sources/privatelink_endpoint_service_data_federation_online_archives.md": true,
}

func main() {
	root := flag.String("root", ".", "repository root directory")
	filtersOut := flag.String("filters", "", "write dorny/paths-filter YAML to this file")
	baseRef := flag.String("base-ref", "", "also exclude docs from this Git revision when generating filters, including removed resources")
	codeownersBlock := flag.Bool("codeowners", false, "print the CODEOWNERS block to stdout")
	update := flag.Bool("update", false, "regenerate the CODEOWNERS block in .github/CODEOWNERS in place")
	check := flag.Bool("check", false, "verify the CODEOWNERS block in .github/CODEOWNERS matches the generated one")
	flag.Parse()

	docsPaths, err := autogenDocsPaths(*root)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}

	switch {
	case *filtersOut != "":
		var newPaths []string
		if *baseRef != "" {
			basePaths, err := autogenDocsPathsAtRef(*root, *baseRef)
			if err != nil {
				fmt.Fprintf(os.Stderr, "error: %v\n", err)
				os.Exit(1)
			}
			// Newly classified autogenerated docs: present in the PR's config
			// but not at the base revision. They are excluded from the regular
			// notification, so they get their own filter to notify the docs
			// team once.
			newPaths = difference(docsPaths, basePaths)
			docsPaths = append(docsPaths, basePaths...)
			sort.Strings(docsPaths)
			docsPaths = slices.Compact(docsPaths)
		}
		if err := writeFilters(*filtersOut, docsPaths, newPaths); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
	case *codeownersBlock:
		fmt.Print(codeownersBlockText(docsPaths))
	case *update:
		if err := updateCodeowners(*root); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
	case *check:
		if err := checkCodeowners(*root); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
	default:
		for _, p := range docsPaths {
			fmt.Println(p)
		}
	}
}

// autogenDocsPaths derives doc paths from configuration independently of file
// existence, so new and deleted docs receive the same classification.
func autogenDocsPaths(root string) ([]string, error) {
	cfg, err := config.ParseGenConfigYAML(filepath.Join(root, configPath))
	if err != nil {
		return nil, fmt.Errorf("parsing %s: %w", configPath, err)
	}

	return docsPathsForConfig(cfg)
}

func autogenDocsPathsAtRef(root, ref string) ([]string, error) {
	data, err := exec.CommandContext(context.Background(), "git", "-C", root, "show", ref+":"+configPath).Output()
	if err != nil {
		return nil, fmt.Errorf("reading %s at %s: %w", configPath, ref, err)
	}
	var cfg config.Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return nil, fmt.Errorf("parsing %s at %s: %w", configPath, ref, err)
	}
	return docsPathsForConfig(&cfg)
}

func docsPathsForConfig(cfg *config.Config) ([]string, error) {
	if len(cfg.Resources) == 0 {
		return nil, fmt.Errorf("%s contains no resources", configPath)
	}
	var result []string
	for name := range cfg.Resources {
		if strings.HasSuffix(name, "_api") {
			// Covered by genericAPIGlobs.
			continue
		}
		var candidates []string
		resource := cfg.Resources[name]
		if resource.Create != nil || resource.Read != nil || resource.Update != nil || resource.Delete != nil {
			candidates = append(candidates, "docs/resources/"+name+".md")
		}
		if ds := resource.DataSources; ds != nil {
			if ds.Read != nil {
				candidates = append(candidates, "docs/data-sources/"+name+".md")
			}
			if ds.List != nil {
				candidates = append(candidates, "docs/data-sources/"+name+"s.md")
			}
		}
		for _, candidate := range candidates {
			if !handwrittenDocs[candidate] {
				result = append(result, candidate)
			}
		}
	}
	sort.Strings(result)
	return result, nil
}

func negated(paths []string) []string {
	result := make([]string, 0, len(paths)+len(genericAPIGlobs))
	for _, glob := range genericAPIGlobs {
		result = append(result, "!"+glob)
	}
	for _, p := range paths {
		result = append(result, "!"+p)
	}
	return result
}

func difference(paths, exclude []string) []string {
	excluded := make(map[string]bool, len(exclude))
	for _, p := range exclude {
		excluded[p] = true
	}
	var result []string
	for _, p := range paths {
		if !excluded[p] {
			result = append(result, p)
		}
	}
	return result
}

func writeFilters(dest string, docsPaths, newDocsPaths []string) error {
	var sb strings.Builder
	sb.WriteString("# Generated by `go run ./tools/autogendocslist -filters`. Do not edit.\n")
	sb.WriteString("files:\n")
	sb.WriteString("  - '.changelog/**'\n")
	sb.WriteString("  - 'docs/**'\n")
	for _, p := range negated(docsPaths) {
		fmt.Fprintf(&sb, "  - '%s'\n", p)
	}
	if len(newDocsPaths) > 0 {
		// Newly autogenerated docs are excluded from the files filter above,
		// but they still get a one-time notification so the docs team sees
		// them when they are introduced.
		sb.WriteString("new_autogen_docs:\n")
		for _, p := range newDocsPaths {
			fmt.Fprintf(&sb, "  - '%s'\n", p)
		}
	}
	return os.WriteFile(dest, []byte(sb.String()), 0o600)
}

func codeownersBlockText(docsPaths []string) string {
	var sb strings.Builder
	sb.WriteString(beginMarker + "\n")
	sb.WriteString(codeownersEntries(docsPaths))
	sb.WriteString(endMarker + "\n")
	return sb.String()
}

func codeownersEntries(docsPaths []string) string {
	var sb strings.Builder
	for _, glob := range genericAPIGlobs {
		fmt.Fprintf(&sb, "/%s %s\n", glob, docsOwner)
	}
	for _, p := range docsPaths {
		fmt.Fprintf(&sb, "/%s %s\n", p, docsOwner)
	}
	return sb.String()
}

func checkCodeowners(root string) error {
	current, err := os.ReadFile(filepath.Join(root, codeownersPath))
	if err != nil {
		return err
	}
	docsPaths, err := autogenDocsPaths(root)
	if err != nil {
		return err
	}
	expected := codeownersEntries(docsPaths)
	if got := extractCodeownersBlock(string(current)); got != expected {
		return fmt.Errorf("CODEOWNERS autogenerated docs block is outdated. Run `make update-autogen-docs-owners` to regenerate it\n\nexpected block:\n%s\ngot block:\n%s", expected, got)
	}
	return nil
}

// updateCodeowners regenerates the marked block in .github/CODEOWNERS in
// place, replacing any existing block or appending one at the end.
func updateCodeowners(root string) error {
	path := filepath.Join(root, codeownersPath)
	current, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	docsPaths, err := autogenDocsPaths(root)
	if err != nil {
		return err
	}
	content := string(current)
	if beginIdx := strings.Index(content, beginMarker); beginIdx >= 0 {
		endIdx := strings.LastIndex(content, endMarker)
		if endIdx < beginIdx {
			return fmt.Errorf("malformed CODEOWNERS block: found %q without a valid %q", beginMarker, endMarker)
		}
		// Trim the newlines after the end marker: the block already ends with
		// one, and keeping the suffix as is would grow the file on every update.
		suffix := strings.TrimLeft(content[endIdx+len(endMarker):], "\n")
		if suffix != "" {
			content = content[:beginIdx] + codeownersBlockText(docsPaths) + "\n" + suffix
		} else {
			content = content[:beginIdx] + codeownersBlockText(docsPaths)
		}
	} else {
		if content != "" && !strings.HasSuffix(content, "\n") {
			content += "\n"
		}
		content += "\n" + codeownersBlockText(docsPaths)
	}
	content = strings.TrimRight(content, "\n") + "\n"
	return os.WriteFile(path, []byte(content), 0o600)
}

func extractCodeownersBlock(content string) string {
	var lines []string
	inBlock := false
	for line := range strings.SplitSeq(content, "\n") {
		switch {
		case line == beginMarker:
			inBlock = true
		case line == endMarker:
			inBlock = false
		case inBlock:
			lines = append(lines, line+"\n")
		}
	}
	return strings.Join(lines, "")
}
